@TestOn('vm')
library;

import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:vibermate_app/core/api/client_protections.dart';
import 'package:vibermate_app/core/api/control_api.dart';
import 'package:vibermate_app/core/api/control_models.dart';
import 'package:vibermate_app/preview/preview_control_api.dart';

void main() {
  // Generated by internal/desktopcontrol (TestClientProtectionsSampleIsCurrent).
  List<Map<String, Object?>> sample() =>
      (jsonDecode(
                File(
                  '../../api/samples/client-protections.json',
                ).readAsStringSync(),
              )
              as List)
          .cast<Map<String, Object?>>();

  Map<String, Object?> answer(List<Object?> protections) => {
    'captureKey': 'managed_run:run-1',
    'client': 'claude-code',
    'protections': protections,
  };

  Map<String, Object?> row({
    String id = 'structured_workspace_tools',
    String basis = 'recognized_client',
    String state = 'inactive',
    String? reason = 'original_destination',
    String appliedBy = 'runtime',
  }) => {
    'id': id,
    'basis': basis,
    'state': state,
    'reason': ?reason,
    'appliedBy': appliedBy,
  };

  test('every answer the Runtime sample holds is read in full', () {
    final entries = sample();
    expect(entries, isNotEmpty);
    final seen = <String>{};
    for (final entry in entries) {
      final parsed = CaptureClientProtections.tryParse(entry);
      expect(parsed, isNotNull, reason: '${entry['captureKey']}');
      expect(parsed!.captureKey, entry['captureKey']);
      expect(parsed.client, entry['client']);
      final rows = (entry['protections']! as List).cast<Map<String, Object?>>();
      // No row of the sample is one this build would leave out.
      expect(parsed.protections, hasLength(rows.length));
      for (final (index, protection) in parsed.protections.indexed) {
        final wire = rows[index];
        expect(protection.id.wire, wire['id']);
        expect(protection.basis.wire, wire['basis']);
        expect(protection.state.wire, wire['state']);
        expect(protection.reason?.wire, wire['reason']);
        expect(protection.appliedBy.wire, wire['appliedBy']);
        seen
          ..add(protection.id.wire)
          ..add(protection.basis.wire)
          ..add(protection.state.wire)
          ..add(protection.appliedBy.wire);
        if (protection.reason case final reason?) seen.add(reason.wire);
      }
    }
    // The sample is the App's only fixture for this route: every value this
    // build knows must appear in it.
    expect(seen, {
      for (final value in ClientProtectionId.values) value.wire,
      for (final value in ClientProtectionBasis.values) value.wire,
      for (final value in ClientProtectionState.values) value.wire,
      for (final value in ClientProtectionReason.values) value.wire,
      for (final value in ClientProtectionApplier.values) value.wire,
    });
    expect(
      entries.any((entry) => (entry['protections']! as List).isEmpty),
      isTrue,
    );
  });

  test('a value this build does not know drops only its row', () {
    for (final unknown in <Map<String, Object?>>[
      row(id: 'shell_tools'),
      row(basis: 'vendor_promise'),
      row(state: 'paused'),
      row(reason: 'maintenance'),
      row(appliedBy: 'companion'),
    ]) {
      final parsed = CaptureClientProtections.tryParse(
        answer([
          row(
            id: 'core_owned_streaming_fallback',
            state: 'on',
            reason: null,
            appliedBy: 'launcher',
          ),
          unknown,
        ]),
      );
      expect(parsed, isNotNull, reason: '$unknown');
      expect(parsed!.protections.map((value) => value.id), [
        ClientProtectionId.coreOwnedStreamingFallback,
      ], reason: '$unknown');
    }
  });

  test('an answer without the route shape gives null', () {
    final good = answer([row()]);
    expect(CaptureClientProtections.tryParse(good), isNotNull);
    expect(
      CaptureClientProtections.tryParse({
        'captureKey': 'managed_run:run-1',
        'protections': <Object?>[],
      })?.client,
      isNull,
    );
    for (final malformed in <Object?>[
      null,
      'managed_run:run-1',
      <Object?>[good],
      {'protections': <Object?>[]},
      {'captureKey': '', 'protections': <Object?>[]},
      {'captureKey': 'managed_run:run-1'},
      {'captureKey': 'managed_run:run-1', 'protections': row()},
      {...good, 'client': ''},
      {...good, 'routingSet': 'work'},
      answer(['structured_workspace_tools']),
      answer([
        {...row(), 'detail': 'extra'},
      ]),
      answer([
        {...row()}..remove('state'),
      ]),
      answer([row(id: '')]),
      answer([
        {...row(), 'basis': 7},
      ]),
      answer([row(reason: '')]),
      // The Runtime gives a reason only for a protection that is not on.
      answer([row(state: 'on')]),
      answer([row(), row(state: 'off', reason: 'operator_disabled')]),
    ]) {
      expect(
        CaptureClientProtections.tryParse(malformed),
        isNull,
        reason: '$malformed',
      );
    }
  });

  group('HTTP reader', () {
    late HttpServer server;
    late HttpControlApi api;
    late int status;
    late Object? body;
    final paths = <String>[];

    setUp(() async {
      paths.clear();
      server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
      server.listen((request) async {
        paths.add(request.uri.path);
        request.response
          ..statusCode = status
          ..headers.contentType = ContentType.json
          ..write(body is String ? body : jsonEncode(body));
        await request.response.close();
      });
      api = await HttpControlApi.connect(
        DesktopSession(
          baseUrl: Uri.parse('http://127.0.0.1:${server.port}'),
          readToken: 'R' * 43,
          writeToken: 'W' * 43,
          instanceId: 'client-protections-test',
          expiresAt: DateTime.now().toUtc().add(const Duration(days: 10)),
        ),
        inspectSession: false,
      );
    });

    tearDown(() async {
      await api.close();
      await server.close(force: true);
    });

    Map<String, Object?> problem(int status, String code) => {
      'type': 'urn:vibermate:error:${code.replaceAll('_', '-')}',
      'title': 'Problem',
      'status': status,
      'code': code,
    };

    test('reads the answer for the Capture it asked about', () async {
      final entry = sample().first;
      final key = entry['captureKey']! as String;
      status = 200;
      body = entry;
      final value = await api.captureClientProtections(key);
      expect(value?.captureKey, key);
      expect(value?.protections, isNotEmpty);
      expect(
        paths.single,
        '/api/v1/captures/${Uri.encodeComponent(key)}/client-protections',
      );
    });

    test('a Runtime without the route, or without the Capture, answers '
        'nothing', () async {
      for (final code in ['control_route_not_found', 'capture_not_found']) {
        status = 404;
        body = problem(404, code);
        expect(
          await api.captureClientProtections('managed_run:run-1'),
          isNull,
          reason: code,
        );
      }
    });

    test('an answer it cannot read answers nothing', () async {
      status = 200;
      for (final unreadable in <Object?>[
        // Another Capture's answer.
        sample().first,
        {'captureKey': 'managed_run:other', 'protections': <Object?>[]},
        {'captureKey': 'managed_run:run-1'},
        'not json',
      ]) {
        body = unreadable;
        expect(
          await api.captureClientProtections('managed_run:run-1'),
          isNull,
          reason: '$unreadable',
        );
      }
    });

    test('a Runtime that cannot answer now reports it', () async {
      status = 503;
      body = problem(503, 'capture_unavailable');
      await expectLater(
        api.captureClientProtections('managed_run:run-1'),
        throwsA(
          isA<ControlProblem>().having(
            (error) => error.reasonCode,
            'reasonCode',
            'capture_unavailable',
          ),
        ),
      );
    });
  });

  test('the preview answers like a Runtime', () async {
    final api = PreviewControlApi();
    addTearDown(api.close);
    expect(api, isA<CaptureProtectionReader>());
    Future<List<(ClientProtectionId, ClientProtectionBasis, String)>> rows(
      String key,
    ) async {
      final value = await api.captureClientProtections(key);
      expect(value?.captureKey, key);
      return [
        for (final protection in value!.protections)
          (
            protection.id,
            protection.basis,
            [
              protection.state.wire,
              ?protection.reason?.wire,
              protection.appliedBy.wire,
            ].join('/'),
          ),
      ];
    }

    // A recognized Claude Code on a routing set that sends it Upstream.
    expect(await rows('managed_run:run-9'), [
      (
        ClientProtectionId.coreOwnedStreamingFallback,
        ClientProtectionBasis.recognizedClient,
        'on/launcher',
      ),
      (
        ClientProtectionId.structuredWorkspaceTools,
        ClientProtectionBasis.recognizedClient,
        'on/runtime',
      ),
    ]);
    // A recognized Codex on the built-in set: nothing to keep alive.
    expect(await rows('managed_run:run-10'), [
      (
        ClientProtectionId.responsesDataKeepalive,
        ClientProtectionBasis.recognizedClient,
        'inactive/original_destination/runtime',
      ),
      (
        ClientProtectionId.responsesWebSocketHttpFallback,
        ClientProtectionBasis.operationCatalog,
        'on/runtime',
      ),
    ]);
    // A known release keeps the protections its release carries.
    expect(await rows('managed_run:run-1'), [
      (
        ClientProtectionId.coreOwnedStreamingFallback,
        ClientProtectionBasis.exactRelease,
        'on/launcher',
      ),
      (
        ClientProtectionId.structuredWorkspaceTools,
        ClientProtectionBasis.exactRelease,
        'on/runtime',
      ),
    ]);
    // A recognized Claude Code on the built-in set: the command leaves its
    // retry alone, and there is no tool decision to make.
    final fresh = api.addFreshRun(
      codex: false,
      phase: PreviewFreshRunPhase.observed,
      recognition: 'recognized',
    );
    expect(await rows('managed_run:$fresh'), [
      (
        ClientProtectionId.coreOwnedStreamingFallback,
        ClientProtectionBasis.recognizedClient,
        'inactive/original_destination/launcher',
      ),
      (
        ClientProtectionId.structuredWorkspaceTools,
        ClientProtectionBasis.recognizedClient,
        'inactive/original_destination/runtime',
      ),
    ]);
    // A build that was not checked gets none.
    final unchecked = api.addFreshRun(
      codex: true,
      phase: PreviewFreshRunPhase.observed,
      recognition: 'unverified',
    );
    final none = await api.captureClientProtections('managed_run:$unchecked');
    expect(none?.client, isNull);
    expect(none?.protections, isEmpty);
    // A manual Capture has no client protections, and an unknown one no
    // answer.
    expect(await rows('manual_capture:manual-figma'), isEmpty);
    expect(await api.captureClientProtections('managed_run:missing'), isNull);
  });
}
